#[derive(Debug, Clone, Copy)]
enum Delimiter {
    VirtualKey(u16),
    Character(char),
}

impl Delimiter {
    fn text(self) -> String {
        match self {
            Self::VirtualKey(VK_SPACE) => " ".to_owned(),
            Self::VirtualKey(VK_TAB) => "\t".to_owned(),
            Self::VirtualKey(VK_RETURN) => "\r\n".to_owned(),
            Self::VirtualKey(_) => String::new(),
            Self::Character(ch) => ch.to_string(),
        }
    }
}

