            object
                .GetIDsOfNames(
                    &GUID::zeroed(),
                    &name_pointer,
                    1,
                    LOCALE_USER_DEFAULT,
                    &mut id,
                )
                .map_err(|error| {
                    trace(&format!(
                        "native-lookup-failed-{name}-hr-{:08x}",
                        error.code().0 as u32
