 fn RegCreateKeyExW(key:Key,path:*const u16,reserved:u32,class:*mut u16,options:u32,access:u32,security:*const c_void,result:*mut Key,disposition:*mut u32)->i32;
 fn RegQueryValueExW(key:Key,name:*const u16,reserved:*mut u32,kind:*mut u32,data:*mut u8,size:*mut u32)->i32;
 fn RegSetValueExW(key:Key,name:*const u16,reserved:u32,kind:u32,data:*const u8,size:u32)->i32;
 fn RegFlushKey(key:Key)->i32;
 fn RegCloseKey(key:Key)->i32;
}
#[link(name="kernel32")]
extern "system" {
 fn CreateMutexW(attributes:*const c_void,owner:i32,name:*const u16)->*mut c_void;
 fn WaitForSingleObject(handle:*mut c_void,millis:u32)->u32;
 fn ReleaseMutex(handle:*mut c_void)->i32;
