}
fn wide(s:&str)->Vec<u16>{s.encode_utf16().chain(Some(0)).collect()}
struct Lock(*mut c_void);
impl Lock {fn take(namespace:&str)->Result<Self,()>{unsafe{
 let encoded:String=namespace.bytes().map(|b|format!("{b:02x}")).collect();let name=wide(&format!("Local\\GSwitcher-WordAdmission-v1-{encoded}"));let h=CreateMutexW(core::ptr::null(),0,name.as_ptr());
 if h.is_null(){return Err(());}let status=WaitForSingleObject(h,0);
 if status!=0 {CloseHandle(h);return Err(());} // abandoned/unknown is not permission
 Ok(Self(h))
}}}
impl Drop for Lock {fn drop(&mut self){unsafe{ReleaseMutex(self.0);CloseHandle(self.0);}}}
struct Registry(Key);
impl Registry {
 fn open(namespace:&str)->Result<Self,()>{unsafe{let path=wide(namespace);let mut key=core::ptr::null_mut();let mut disposition=0;
 if RegCreateKeyExW(HKCU,path.as_ptr(),0,core::ptr::null_mut(),0,3,core::ptr::null(),&mut key,&mut disposition)!=0{return Err(());}Ok(Self(key))}}
