 fn read(&self,host:Host)->Result<Option<Vec<u8>>,()>{unsafe{
 let name=Self::name(host);let mut kind=0;let mut size=0;
 let status=RegQueryValueExW(self.0,name.as_ptr(),core::ptr::null_mut(),&mut kind,core::ptr::null_mut(),&mut size);
 if status==2{return Ok(None);}if status!=0||kind!=3||size==0||size>512{return Err(());}
