 }
 fn matches(&self,host:Host,marker:&[u8])->bool{( || {let _lock=Lock::take(&self.namespace)?;let key=Registry::open(&self.namespace)?;Ok::<_,()>(key.read(host)?.as_deref()==Some(marker))})().unwrap_or_else(|()|{super::trace(5,"storage-or-lock-unavailable");false})}
