//! One bounded, read-only provider worker. No mutation is allowed here.
//! After a timeout, refuse new work until the exact old call completed.
//! Discard its late reply; resume only with a new request on the same thread.
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::{self, SyncSender, TryRecvError};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

struct Read<Q, R> {
    input: Q,
    result: SyncSender<R>,
    completed: Arc<AtomicBool>,
    #[cfg(windows)]
    provider_permit: Option<super::word_admission::ReaderChild>,
}

#[derive(Default)]
struct ReaderState {
    in_flight: Option<Arc<AtomicBool>>,
    caller_active: bool,
    timed_out: bool,
    disconnected: bool,
}

pub struct BoundedReader<Q, R> {
    requests: SyncSender<Read<Q, R>>,
    state: Mutex<ReaderState>,
}

impl<Q: Send + 'static, R: Send + 'static> BoundedReader<Q, R> {
    pub fn start(mut process: impl FnMut(Q) -> R + Send + 'static) -> std::io::Result<Self> {
        let (requests, queue) = mpsc::sync_channel::<Read<Q, R>>(1);
        std::thread::Builder::new()
            .name("g-switcher-uia-reader".into())
            .spawn(move || {
                while let Ok(request) = queue.recv() {
                    #[cfg(windows)]
                    let result = match request.provider_permit.as_ref() {Some(permit)=>permit.run(||process(request.input)),None=>process(request.input)};
                    #[cfg(not(windows))]
                    let result = process(request.input);
                    // Completion acknowledges provider quiescence only. It
                    // never grants writable/security authority to the caller.
                    #[cfg(windows)]
                    if let Some(permit) = request.provider_permit {
                        let _ = permit.complete();
                    }
                    request.completed.store(true, Ordering::Release);
                    let _ = request.result.try_send(result);
                }
            })?;
        Ok(Self {
            requests,
            state: Mutex::new(ReaderState::default()),
        })
    }

    pub fn request(&self, input: Q, timeout: Duration) -> Option<R> {
        self.request_inner(input, timeout, #[cfg(windows)] None)
    }
    #[cfg(windows)]
    pub(crate) fn request_guarded(&self, input: Q, timeout: Duration, parent: &super::word_admission::Parent) -> Option<R> {
        self.request_inner(input, timeout, Some(parent))
    }
    fn request_inner(&self, input: Q, timeout: Duration, #[cfg(windows)] parent: Option<&super::word_admission::Parent>) -> Option<R> {
        let deadline = Instant::now().checked_add(timeout)?;
        let completed = Arc::new(AtomicBool::new(false));
        let recovered = {
            let mut state = self.state.try_lock().ok()?;
            if state.disconnected || state.caller_active {
                return None;
            }
            if state
                .in_flight
                .as_ref()
                .is_some_and(|old| !old.load(Ordering::Acquire))
            {
                return None;
            }
            let recovered = state.timed_out;
            state.timed_out = false;
            state.in_flight = Some(completed.clone());
            state.caller_active = true;
            recovered
        };
        struct Caller<'a>(&'a Mutex<ReaderState>);
        impl Drop for Caller<'_> {
            fn drop(&mut self) {
                if let Ok(mut state) = self.0.lock() {
                    state.caller_active = false;
                }
            }
        }
        let _caller = Caller(&self.state);
        if recovered {
            trace_reader("reader-recovered-fresh-request");
        }
        #[cfg(windows)]
        let provider_permit = match parent {
            Some(parent) => match parent.child() {Some(ticket) => Some(ticket), None => {completed.store(true,Ordering::Release); return None;}},
            None => None,
        };
        let (result, response) = mpsc::sync_channel(1);
        if let Err(error) = self.requests.try_send(Read {
            input, result, completed,
            #[cfg(windows)] provider_permit,
        }) {
            let request = match error {mpsc::TrySendError::Full(r) | mpsc::TrySendError::Disconnected(r) => r};
            request.completed.store(true,Ordering::Release);
            #[cfg(windows)] if let Some(permit)=request.provider_permit {let _=permit.complete();}
            self.state.lock().ok()?.disconnected = true;
            trace_reader("reader-disconnected");
            return None;
        }
        loop {
            pump_sent_messages();
            if Instant::now() >= deadline {
                self.state.lock().ok()?.timed_out = true;
                trace_reader("reader-timeout-awaiting-old-completion");
                return None;
            }
            match response.try_recv() {
                Ok(value) => return Some(value),
                Err(TryRecvError::Disconnected) => {
                    self.state.lock().ok()?.disconnected = true;
                    trace_reader("reader-disconnected");
                    return None;
                }
                Err(TryRecvError::Empty) => std::thread::sleep(Duration::from_millis(1)),
            }
        }
    }
}

fn trace_reader(stage: &str) {
    use std::io::Write;
    let path = std::env::temp_dir().join("GSwitcher-Word-Runtime.log");
    let oversized = std::fs::metadata(&path).is_ok_and(|meta| meta.len() > 1_048_576);
    if let Ok(mut file) = std::fs::OpenOptions::new()
        .create(true)
        .write(true)
        .append(!oversized)
        .truncate(oversized)
        .open(path)
    {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis();
        let _ = writeln!(file, "{now} pid={} stage={stage}", std::process::id());
    }
}

pub fn pump_sent_messages() {
    #[cfg(windows)]
    unsafe {
        use windows_sys::Win32::UI::WindowsAndMessaging::{PeekMessageW, MSG, PM_NOREMOVE};
        let mut message: MSG = std::mem::zeroed();
        // PeekMessage dispatches pending nonqueued sent messages even when no
        // posted message is removed. Do not Translate/Dispatch posted messages.
        PeekMessageW(&mut message, std::ptr::null_mut(), 0, 0, PM_NOREMOVE);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{Arc, Condvar, Mutex};
    use std::time::{Duration, Instant};

    #[cfg(windows)]
    fn guarded_timeout_lifecycle(uncertain:bool){
        use super::super::word_admission::Fixture;
        let fixture=Fixture::new();let parent=fixture.parent.clone();
        let (entered,entry)=mpsc::channel();let (release,held)=mpsc::channel();
        let reader=BoundedReader::start(move |()|{entered.send(()).unwrap();held.recv().unwrap();42}).unwrap();
        assert_eq!(reader.request_guarded((),Duration::from_millis(750),&parent),None);
        entry.recv_timeout(Duration::from_secs(1)).unwrap(); // Actual worker entered, no fake zero-call assertion.
        assert!(fixture.pending());assert!(parent.complete(uncertain));assert!(fixture.pending());
        release.send(()).unwrap();
        let deadline=Instant::now()+Duration::from_secs(2);
        loop {
            let complete=reader.state.lock().unwrap().in_flight.as_ref().unwrap().load(Ordering::Acquire);
            if complete{break;}
            assert!(Instant::now()<deadline);std::thread::sleep(Duration::from_millis(1));
        }
        if uncertain{assert!(fixture.pending());assert!(!fixture.idle());}
        else{assert!(fixture.idle());assert!(!fixture.pending());}
    }
    #[cfg(windows)] #[test] fn guarded_actual_reader_keeps_marker_after_caller_timeout_until_worker_returns(){guarded_timeout_lifecycle(false);}
    #[cfg(windows)] #[test] fn guarded_actual_reader_late_completion_never_clears_uncertainty(){guarded_timeout_lifecycle(true);}

    #[test]
    fn provider_runs_off_the_requesting_thread() {
        let caller = std::thread::current().id();
        let reader = BoundedReader::start(|()| std::thread::current().id()).unwrap();
        let observed = reader
            .request((), Duration::from_secs(1))
            .expect("metadata worker must respond");
        assert_ne!(observed, caller);
    }

    #[test]
    fn stalled_metadata_returns_none_and_never_queues_a_replacement() {
        let gate = Arc::new((Mutex::new(false), Condvar::new()));
        let calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let worker_gate = gate.clone();
        let worker_calls = calls.clone();
        let reader = BoundedReader::start(move |value| {
            worker_calls.fetch_add(1, Ordering::SeqCst);
            let (lock, wake) = &*worker_gate;
            let _guard = wake
                .wait_while(lock.lock().unwrap(), |ready| !*ready)
                .unwrap();
            value
        })
        .unwrap();
        // Baseline synchronous behavior is released eventually, so RED cannot hang.
        let release = gate.clone();
        let releaser = std::thread::spawn(move || {
            std::thread::sleep(Duration::from_millis(250));
            *release.0.lock().unwrap() = true;
            release.1.notify_all();
        });
        let started = Instant::now();
        let result = reader.request(42, Duration::from_millis(20));
        let elapsed = started.elapsed();
        let second = reader.request(43, Duration::from_millis(20));
        releaser.join().unwrap();
        assert_eq!(
            result, None,
            "late metadata must not become writable authority"
        );
        assert!(
            elapsed < Duration::from_millis(200),
            "caller blocked {elapsed:?}"
        );
        assert_eq!(second, None, "a timed-out reader remains quarantined");
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        let deadline = Instant::now() + Duration::from_secs(1);
        loop {
            if let Some(value) = reader.request(44, Duration::from_millis(100)) {
                assert_eq!(value, 44);
                break;
            }
            assert!(Instant::now() < deadline);
            std::thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(calls.load(Ordering::SeqCst), 2);
    }

    #[test]
    fn each_successful_request_reads_fresh_state() {
        let mut revision = 0;
        let reader = BoundedReader::start(move |()| {
            revision += 1;
            revision
        })
        .unwrap();
        assert_eq!(reader.request((), Duration::from_secs(1)), Some(1));
        assert_eq!(reader.request((), Duration::from_secs(1)), Some(2));
    }

    #[test]
    fn provider_failure_returns_none_without_panicking_the_caller() {
        let reader = BoundedReader::<(), ()>::start(|()| panic!("provider failed")).unwrap();
        assert_eq!(reader.request((), Duration::from_secs(1)), None);
        assert_eq!(reader.request((), Duration::from_secs(1)), None);
    }
}

